def set_left_most_unset_bit(n):
    if n == 0:
        return 1

    # Find the position of the leftmost unset bit (starting from LSB)
    # We iterate through bits until we find an unset one
    result = n
    for i in range(32):
        if not ((n >> i) & 1):
            # Found an unset bit at position i, set it and return the new value
            return result | (1 << i)

